INSERT INTO verses (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(47711, 'Ezekiel 40:21', 'Ezekiel', 40, 21, 'درې وړې کوټې چې د دروازې د دهلېز په دواړو خواو کې وې، د هغو په منځ کې دېوالونه او د دنننۍ کوټې اندازه د ختیځې دروازې سره یوشان وه. د دروازې اوږدوالی پنځه ویشت متره او سور یې دولس نیم متره ؤ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel40_verse_21.mp3', '', 1761754199, 1761754199),
(47712, 'Ezekiel 40:22', 'Ezekiel', 40, 22, 'د کړکۍ‌ګانو، دهلېز او د خرما د ونو د تصویرونو اندازه هماغه شان وه، لکه څنګه چې په ختیځې دروازې کې وه. په دې ځای کې شمالي دروازې ته یوه زینه ورختلې وه چې اووه پوړۍ یې درلودلې او دهلېز ته مخامخ وه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel40_verse_22.mp3', '', 1761754199, 1761754199),
(47713, 'Ezekiel 40:23', 'Ezekiel', 40, 23, 'شمالي دروازې ته مخامخ د حوېلۍ دننه خواته یوه بله دروازه وه لکه څنګه چې ختیځې خواته وه. هغه سړي د دې دواړو دروازو ترمنځ فاصله اندازه کړه او هغه پنځوس متره وه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel40_verse_23.mp3', '', 1761754199, 1761754199),
(47714, 'Ezekiel 40:24', 'Ezekiel', 40, 24, 'بیا هغه سړي زه د جنوب خواته بوتلم او هلته مې یوه بله دروازه ولیدله. هغه دننني دېوالونه او دهلېز اندازه کړ او هغه هم د نورو دروازو په اندازه وو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel40_verse_24.mp3', '', 1761754199, 1761754199),
(47715, 'Ezekiel 40:25', 'Ezekiel', 40, 25, 'د دې دروازې او د دروازې دهلېز هماغه شان کړکۍ‌ګانې درلودلې لکه څنګه چې په نورو دروازو کې وې. د ننوتلو د دهلېز ټول اوږدوالی پنځه ویشت متره او سور یې دولس نیم متره ؤ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel40_verse_25.mp3', '', 1761754199, 1761754199),
(47716, 'Ezekiel 40:26', 'Ezekiel', 40, 26, 'دې دروازې ته یوه زینه ورختلې وه چې اووه پوړۍ یې لرلې او دهلېز ته مخامخ وه. د هغه دننني دېوالونو دواړې خواوې چې د تېرېدلو لارې ته مخامخ وو، د خرما د ونو په تصویرونو باندې ښکلي کړای شوي وو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel40_verse_26.mp3', '', 1761754199, 1761754199),
(47717, 'Ezekiel 40:27', 'Ezekiel', 40, 27, 'دلته هم باندینۍ حوېلۍ ته مخامخ د دنننۍ حوېلۍ جنوب خواته یوه دروازه وه. هغه سړي د دنننۍ دروازې نه جنوب خواته تر باندینۍ دروازې پورې فاصله اندازه کړه، هغه پنځوس متره وه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel40_verse_27.mp3', '', 1761754199, 1761754199),
(47718, 'Ezekiel 40:28', 'Ezekiel', 40, 28, 'هغه سړي زه د جنوبي دروازې په لاره دنننۍ حوېلۍ ته بوتلم. هغه دروازه اندازه کړه او د هغې اندازه د باندینیو دروازو سره یوشان وه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel40_verse_28.mp3', '', 1761754199, 1761754199),
(47719, 'Ezekiel 40:29', 'Ezekiel', 40, 29, 'د وړو کوټو، د هغه د دنننیو دېوالونو او د دهلېز اندازه د نورو دروازو سره یوشان وه. همدارنګه دې دروازې او دهلېز شاوخوا کړکۍ‌ګانې درلودلې. د هغو ټول اوږدوالی پنځه ویشت متره او سور یې دولس نیم متره ؤ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel40_verse_29.mp3', '', 1761754199, 1761754199),
(47720, 'Ezekiel 40:30', 'Ezekiel', 40, 30, 'شاوخوا په دنننۍ حوېلۍ کې نور دهلېزونه هم وو چې اوږدوالی یې دولس نیم متره او سور یې دوه نیم متره ؤ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel40_verse_30.mp3', '', 1761754199, 1761754199),
(47721, 'Ezekiel 40:31', 'Ezekiel', 40, 31, 'د جنوبي دروازې دهلېز باندینۍ حوېلۍ ته مخامخ ؤ او دېوال یې د خرما د ونو په تصویرونو باندې ښکلي کړای شوي وو. دروازې ته یوه زینه ورختلې وه چې اته پوړۍ یې لرلې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel40_verse_31.mp3', '', 1761754199, 1761754199),
(47722, 'Ezekiel 40:32', 'Ezekiel', 40, 32, 'هغه سړي زه د ختیځې دروازې په لاره دنننۍ حوېلۍ ته بوتلم. هغه دروازه اندازه کړه او د هغې اندازه د نورو دروازو سره یوشان وه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel40_verse_32.mp3', '', 1761754199, 1761754199),
(47723, 'Ezekiel 40:33', 'Ezekiel', 40, 33, 'د وړو کوټو، د هغه د دنننیو دېوالونو او د دهلېز اندازه د نورو دروازو سره یوشان وه. همدارنګه دې دروازې او دهلېز شاوخوا کړکۍ‌ګانې درلودلې. د هغو ټول اوږدوالی پنځه ویشت متره او سور یې دولس نیم متره ؤ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel40_verse_33.mp3', '', 1761754199, 1761754199),
(47724, 'Ezekiel 40:34', 'Ezekiel', 40, 34, 'د ختیځې دروازې دهلېز باندینۍ حوېلۍ ته مخامخ ؤ. دېوال یې په دواړو خواوو د خرما د ونو په تصویرونو باندې ښکلي کړای شوي وو. دروازې ته یوه زینه ورختلې وه چې اته پوړۍ یې لرلې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel40_verse_34.mp3', '', 1761754199, 1761754199),
(47725, 'Ezekiel 40:35', 'Ezekiel', 40, 35, 'بیا هغه سړي زه شمالي دروازې ته بوتلم. هغه یې اندازه کړه او د هغې اندازه د نورو دروازو سره یوشان وه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel40_verse_35.mp3', '', 1761754199, 1761754199),
(47726, 'Ezekiel 40:36', 'Ezekiel', 40, 36, 'د وړو کوټو، د هغه د دنننیو دېوالونو او دهلېز اندازه د نورو دروازو سره یوشان وه. همدارنګه شاوخوا یې کړکۍ‌ګانې درلودلې. د هغو ټول اوږدوالی پنځه ویشت متره او سور یې دولس نیم متره ؤ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel40_verse_36.mp3', '', 1761754199, 1761754199),
(47727, 'Ezekiel 40:37', 'Ezekiel', 40, 37, 'د شمالي دروازې دهلېز باندینۍ حوېلۍ ته مخامخ ؤ. دېوال یې په دواړو خواوو د خرما د ونو په تصویرونو باندې ښکلي کړای شوی ؤ. دروازې ته یوه زینه ورختلې وه چې اته پوړۍ یې لرلې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel40_verse_37.mp3', '', 1761754199, 1761754199),
(47728, 'Ezekiel 40:38', 'Ezekiel', 40, 38, 'د هرې دنننۍ دروازې په څنګ کې یوه کوټه وه چې دروازه یې درلودله او په دې کوټو کې به هغوی د سوځېدونکو قربانیو غوښې وینځلې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel40_verse_38.mp3', '', 1761754199, 1761754199),
(47729, 'Ezekiel 40:39', 'Ezekiel', 40, 39, 'د ننوتلو په کوټه کې څلور مېزونه وو چې د کوټې دواړو خواو ته دوه دوه مېزونه ایښودل شوي وو. په دې مېزونو باندې به هغوی حیوانات حلالول چې د سوځېدونکو نذرانو، د ګناه د نذرانو او د تاوان د نذرانو په توګه یې وړاندې کړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel40_verse_39.mp3', '', 1761754199, 1761754199),
(47730, 'Ezekiel 40:40', 'Ezekiel', 40, 40, 'کله چې خلک د شمال دنننۍ دروازې ته پورته کېدل، د دروازې د خولې څخه دباندې په دواړو خواوو کې دوه دوه مېزونه لیدل کېدل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel40_verse_40.mp3', '', 1761754199, 1761754199),
(47731, 'Ezekiel 40:41', 'Ezekiel', 40, 41, 'ټول اته مېزونه وو چې د قربانۍ حیوانات به ورباندې حلالېدل چې څلور یې دننه په کوټه کې او څلور یې د کوټې نه دباندې په حوېلۍ کې وو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel40_verse_41.mp3', '', 1761754199, 1761754199),
(47732, 'Ezekiel 40:42', 'Ezekiel', 40, 42, 'هلته څلور مېزونه نور هم وو چې د سوځېدونکو نذرانو د تیارولو دپاره ورڅخه کار اخیستل کېده او هغه د توږل شویو تیږو نه جوړ شوي وو. په دې مېزونو باندې به یې هغه سامان ایښوده چې د قربانۍ حیوانات به یې ورباندې حلالول. د دې مېزونو لوړوالی پنځوس سانتي متره او سرونه یې پنځه اویا سانتي متره مربع وو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel40_verse_42.mp3', '', 1761754199, 1761754199),
(47733, 'Ezekiel 40:43', 'Ezekiel', 40, 43, 'د مېزونو نه ګردچاپېره چنګکونه تړل شوي وو چې پنځه اویا ملي متره اوږدوالی یې درلود. د نذرانې غوښه به په دې مېزونو باندې ایښودل کېدله.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel40_verse_43.mp3', '', 1761754199, 1761754199),
(47734, 'Ezekiel 40:44', 'Ezekiel', 40, 44, 'بیا هغه زه دنننۍ حوېلۍ ته بوتلم. په دنننۍ حوېلۍ کې دوه کوټې وې، یوه یې جنوب خواته مخامخ وه چې د شمالي دروازې په څنګ کې وه او بله یې شمال خواته مخامخ وه چې د جنوبي دروازې په څنګ کې وه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel40_verse_44.mp3', '', 1761754199, 1761754199),
(47735, 'Ezekiel 40:45', 'Ezekiel', 40, 45, 'هغه سړي ماته وویل چې جنوب خواته مخامخ کوټه د هغو کاهنانو دپاره ده چې د عبادت په ځای کې مسوولان دي،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel40_verse_45.mp3', '', 1761754199, 1761754199),
(47736, 'Ezekiel 40:46', 'Ezekiel', 40, 46, 'او شمال خواته مخامخ کوټه د هغو کاهنانو دپاره ده چې د قربانۍ د ځای مسوولان دي. ټول کاهنان د صادوق اولاده ده، هغوی د لاوي د قبیلې یوازېني خلک دي چې ورته اجازه شته چې د څښتن حضور ته ورشي او د هغه خدمت وکړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel40_verse_46.mp3', '', 1761754199, 1761754199),
(47737, 'Ezekiel 40:47', 'Ezekiel', 40, 47, 'هغه سړي دنننۍ حوېلۍ اندازه کړه او هغه پنځوس متر مربع وه. د هغې مخامخ د قربانۍ ځای ؤ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel40_verse_47.mp3', '', 1761754199, 1761754199),
(47738, 'Ezekiel 40:48', 'Ezekiel', 40, 48, 'بیا هغه زه د عبادتځای دهلېز ته بوتلم او د دروازې چوکاټ یې اندازه کړ. هغه دوه نیم متره مربع ؤ، د دروازې سور اووه متره ؤ او د دېوالونو د دواړو خواو پنډوالی یونیم متر ؤ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel40_verse_48.mp3', '', 1761754199, 1761754199),
(47739, 'Ezekiel 40:49', 'Ezekiel', 40, 49, 'دهلېز ته لس پوړېزه زینه ورختلې وه. د دې کوټې اوږدوالی لس متره او سور یې شپږ متره ؤ. د ننوتلو د دروازې دواړو خواو ته یوه یوه ستنه وه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel40_verse_49.mp3', '', 1761754199, 1761754199),
(47740, 'Exodus 4:1', 'Exodus', 4, 1, 'موسی په ځواب کې وویل: «فرض کړه که چېرې اسراییلیان زما په خبرو باندې باور ونه کړي او ماته غوږ ونه نیسي او ووایي چې څښتن تاته نه دی ښکاره شوی، نو بیا څه وکړم؟»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus4_verse_1.mp3', '', 1761754199, 1761754199),
(47741, 'Exodus 4:2', 'Exodus', 4, 2, 'څښتن د موسی څخه پوښتنه وکړه: «ستا په لاس کې څه دي؟» موسی په ځواب کې وویل: «امسا.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus4_verse_2.mp3', '', 1761754199, 1761754199),
(47742, 'Exodus 4:3', 'Exodus', 4, 3, 'خدای وویل: «هغه په ځمکه باندې وغورځوه.» کله چې هغه امسا په ځمکه وغورځوله، نو امسا په مار بدله شوه او هغه ورڅخه منډه کړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus4_verse_3.mp3', '', 1761754199, 1761754199),
(47743, 'Exodus 4:4', 'Exodus', 4, 4, 'بیا څښتن ورته وویل: «هغه د لکۍ څخه ونیسه.» نو موسی هغه راونیوه او مار بېرته په امسا بدل شو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus4_verse_4.mp3', '', 1761754199, 1761754199),
(47744, 'Exodus 4:5', 'Exodus', 4, 5, 'څښتن موسی ته وویل: «داسې کار وکړه. بیا به اسراییلیان باور وکړي چې تا زه لیدلی یم چې ستاسو د نیکونو ابراهیم، اسحاق او یعقوب خدای یم.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus4_verse_5.mp3', '', 1761754199, 1761754199),
(47745, 'Exodus 4:6', 'Exodus', 4, 6, 'خدای موسی ته بیا وویل: «خپل لاس دې په ګرېوان کې ننباسه.» هغه همداسې وکړل او کله چې هغه خپل لاس د ګرېوان څخه راوویسته هغه ولیدل چې لاس یې د پوستکي په ناروغۍ باندې اخته شوی ؤ او لکه د واورې په شان سپین شوی ؤ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus4_verse_6.mp3', '', 1761754199, 1761754199),
(47746, 'Exodus 4:7', 'Exodus', 4, 7, 'خدای بیا ورته وویل: «لاس دې بېرته په ګرېوان کې ننباسه.» موسی هماغه شان وکړل. کله چې هغه خپل لاس بېرته راوویسته، د هغه لاس د هغه د نور بدن په شان روغ ؤ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus4_verse_7.mp3', '', 1761754199, 1761754199),
(47747, 'Exodus 4:8', 'Exodus', 4, 8, 'څښتن وویل: «که چېرې هغوی ستا په خبره باور ونه کړي یا په لومړنۍ معجزې باندې قانع نه شي، نو بیا به په دې معجزې باندې قانع شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus4_verse_8.mp3', '', 1761754199, 1761754199),
(47748, 'Exodus 4:9', 'Exodus', 4, 9, 'که چېرې د دغو دوو معجزو سره سره بیاهم هغوی په تا باور ونه کړي او ستا خبرو ته غوږ ونه نیسي، نو د نیل د سیند څخه لږې اوبه راواخله او په ځمکه باندې یې توی کړه. هغه اوبه به په وینه بدلې شي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus4_verse_9.mp3', '', 1761754199, 1761754199),
(47749, 'Exodus 4:10', 'Exodus', 4, 10, 'خو موسی وویل: «څښتنه، ما مه لېږه. زه هېڅکله هم ښه ویاند نه وم. د اول نه هم نه وم او نه له هغه وخت څخه چې تا زما سره خبرې وکړې. زه په خبرو کولو کې کمزوری یم او ژبه مې نښلي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus4_verse_10.mp3', '', 1761754199, 1761754199),
(47750, 'Exodus 4:11', 'Exodus', 4, 11, 'څښتن هغه ته وویل: «هغه څوک دی چې انسان ته یې ژبه ورکړې ده؟ چا کاڼه، ګونګیان، بینا او ړانده پیدا کړل؟ زه څښتن یم او دا هرڅه کوم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus4_verse_11.mp3', '', 1761754199, 1761754199),
(47751, 'Exodus 4:12', 'Exodus', 4, 12, 'اوس لاړ شه! زه به ستا سره په خبرو کولو کې مرسته وکړم او درته وبه وایم چې څه ووایې.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus4_verse_12.mp3', '', 1761754199, 1761754199),
(47752, 'Exodus 4:13', 'Exodus', 4, 13, 'خو موسی وویل: «څښتنه، ته بل څوک ولېږه چې دا کار وکړي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus4_verse_13.mp3', '', 1761754199, 1761754199),
(47753, 'Exodus 4:14', 'Exodus', 4, 14, 'څښتن په موسی باندې په قهر شو او ویې ویل: «ایا ستا ورور لاوي هارون نشته؟ هغه ښې خبرې کولای شي. هغه ستا د لیدنې کتنې دپاره راځي او ستا په لیدلو به خوشحاله شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus4_verse_14.mp3', '', 1761754199, 1761754199),
(47754, 'Exodus 4:17', 'Exodus', 4, 17, 'اوس دا امسا واخله او په هغې باندې معجزې ښکاره کوه.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus4_verse_17.mp3', '', 1761754199, 1761754199),
(47755, 'Exodus 4:18', 'Exodus', 4, 18, 'موسی خپل خسر یعنې یترون ته ورغی او هغه ته یې وویل: «ما پرېږده چې مصر ته لاړ شم چې وګورم زما خپلوان لا ژوندي دي او که نه.» یترون هغه ته وویل: «ځه په خیر لاړ شې.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus4_verse_18.mp3', '', 1761754199, 1761754199),
(47756, 'Exodus 4:19', 'Exodus', 4, 19, 'موسی لا د مدیان په خاوره کې ؤ چې څښتن هغه ته وویل: «مصر ته ستون شه. چا چې غوښتل تا ووژني هغوی اوس مړه دي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus4_verse_19.mp3', '', 1761754199, 1761754199),
(47757, 'Exodus 4:20', 'Exodus', 4, 20, 'نو موسی خپله ښځه او زامن په خره باندې سپاره کړل او د مصر په لور روان شو. موسی هغه امسا هم له ځان سره یووړه د کومې په هکله چې خدای ورته ویلي وو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus4_verse_20.mp3', '', 1761754199, 1761754199),
(47758, 'Exodus 4:21', 'Exodus', 4, 21, 'څښتن بیا موسی ته وویل: «اوس چې ته بېرته مصر ته روان یې، فرعون ته هغه معجزې وښایه چې تاته مې د هغو د ښودلو قدرت درکړی دی. خو زه به د فرعون زړه سخت کړم او هغه به قوم پرېنږدي چې لاړ شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus4_verse_21.mp3', '', 1761754199, 1761754199),
(47759, 'Exodus 4:22', 'Exodus', 4, 22, 'بیا فرعون ته ووایه چې څښتن وایي: ‹اسراییل زما دپاره لکه د مشر زوی په شان دی.›', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus4_verse_22.mp3', '', 1761754199, 1761754199),
(47760, 'Exodus 4:23', 'Exodus', 4, 23, 'ما تاته حکم وکړ چې هغوی پرېږده چې د مصر څخه ووځي او زما عبادت وکړي، خو تا انکار وکړ. نو اوس به زه ستا مشر زوی ووژنم.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus4_verse_23.mp3', '', 1761754199, 1761754199),
(47761, 'Exodus 4:24', 'Exodus', 4, 24, 'د مصر په لاره کې چېرته چې هغوی شپه تېروله، څښتن د موسی سره مخامخ شو او نژدې ؤ چې هغه ووژني.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus4_verse_24.mp3', '', 1761754199, 1761754199),
(47762, 'Exodus 4:27', 'Exodus', 4, 27, 'څښتن هارون ته وویل: «د موسی د لیدلو دپاره دښتې ته لاړ شه.» نو هارون د موسی د لیدلو دپاره سپېڅلي غره ته لاړ او کله چې ورسره مخامخ شو، هغه یې ښکل کړ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus4_verse_27.mp3', '', 1761754199, 1761754199),
(47763, 'Exodus 4:28', 'Exodus', 4, 28, 'بیا موسی هغه ټول شیان چې څښتن ورته ویلي وو او همدارنګه د هغو معجزو په هکله چې هغه ته یې د هغو د ښودلو حکم ورکړی ؤ، هارون ته وویل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus4_verse_28.mp3', '', 1761754199, 1761754199),
(47764, 'Exodus 4:29', 'Exodus', 4, 29, 'نو موسی او هارون مصر ته لاړل او د اسراییلو ټول مشران یې راټول کړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus4_verse_29.mp3', '', 1761754199, 1761754199),
(47765, 'Exodus 4:30', 'Exodus', 4, 30, 'هغه ټول شیان چې څښتن موسی ته ویلي وو، هارون هغوی ته بیان کړل او بیا موسی خلکو ته هغه معجزې وروښودلې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus4_verse_30.mp3', '', 1761754199, 1761754199),
(47766, 'Exodus 4:31', 'Exodus', 4, 31, 'مشران زر په دې باندې قانع شول چې موسی او هارون د څښتن له خوا رالېږل شوي دي. کله چې هغوی پوه شول چې څښتن د هغوی بدبختي لیدلې ده او د هغوی دپاره زیات اندېښمن دی، نو ټول په سجده شول او عبادت یې وکړ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus4_verse_31.mp3', '', 1761754199, 1761754199),
(47767, 'Job 29:1', 'Job', 29, 1, 'ايُوب خپله خبره بيا شروع کړه او وې فرمائيل،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job29_verse_1.mp3', '', 1761754199, 1761754199),
(47768, 'Job 29:2', 'Job', 29, 2, '”کاش چې تېر عُمر زما بيا راغلے وے، چې په کوم وخت کښې د خُدائ پاک په ما باندې نظر وو،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job29_verse_2.mp3', '', 1761754199, 1761754199),
(47769, 'Job 29:3', 'Job', 29, 3, 'هغۀ ما ته رڼا کړه کله چې زۀ په تيارۀ کښې ګرځېدم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job29_verse_3.mp3', '', 1761754199, 1761754199),
(47770, 'Job 29:4', 'Job', 29, 4, 'کله چې زۀ په ځوانۍ کښې وم، او د خُدائ پاک د دوستۍ نظر زما په کور باندې وو،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job29_verse_4.mp3', '', 1761754199, 1761754199),
(47771, 'Job 29:5', 'Job', 29, 5, 'کله چې قادر خُدائ زما مل وو، او زما بچى زما نه ګېرچاپېره تاو وُو،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job29_verse_5.mp3', '', 1761754199, 1761754199),
(47772, 'Job 29:6', 'Job', 29, 6, 'کله چې ما کره پئ ډېر تېر وُو، او ما کره تېل د نِهرونو په شان بهېدل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job29_verse_6.mp3', '', 1761754199, 1761754199),
(47773, 'Job 29:7', 'Job', 29, 7, 'کله چې زۀ د ښار دروازې ته تلم، او د جرګې په ځائ کښې به د عزتمندو مشرانو سره کښېناستم،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job29_verse_7.mp3', '', 1761754199, 1761754199),
(47774, 'Job 29:8', 'Job', 29, 8, 'نو ځوانان به پاڅېدل او لا به ړل، او بوډاګان به اوچت شول او وبه درېدل،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job29_verse_8.mp3', '', 1761754199, 1761754199),
(47775, 'Job 29:9', 'Job', 29, 9, 'مشران خلق به چپ شول، او په خپلو خُلو به يې لاسونه کېښودل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job29_verse_9.mp3', '', 1761754199, 1761754199),
(47776, 'Job 29:10', 'Job', 29, 10, 'د خانانو آوازونه به غلى شول، او د هغوئ د خولې نه به يوه خبره هم نۀ وتله.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job29_verse_10.mp3', '', 1761754199, 1761754199),
(47777, 'Job 29:11', 'Job', 29, 11, 'هر چا به چې زما په حقله اورېدل نو هغوئ به زما صِفت کولو. چې هر چا به زۀ ليدلم نو هغوئ به زما ښۀ وئيل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job29_verse_11.mp3', '', 1761754199, 1761754199),
(47778, 'Job 29:12', 'Job', 29, 12, 'کله به چې غريبانانو څۀ غوښتل نو ما به يې مدد کولو، او د حاجتمندو يتيمانانو مرسته به مې کوله.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job29_verse_12.mp3', '', 1761754199, 1761754199),
(47779, 'Job 29:13', 'Job', 29, 13, 'چې څوک به سخت غمژن وُو نو هغوئ به زما ښۀ وئيل، او زما په وجه به کونډو د خوشحالۍ سندرې وئيلې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job29_verse_13.mp3', '', 1761754199, 1761754199),
(47780, 'Job 29:14', 'Job', 29, 14, 'ما د صداقت هر يو کار کولو، اِنصاف او صداقت د يوې چُوغې او د پټکى په شان وو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job29_verse_14.mp3', '', 1761754199, 1761754199),
(47781, 'Job 29:15', 'Job', 29, 15, 'زۀ د ړندو دپاره سترګې وم، او د ګوډيانو دپاره پښې وم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job29_verse_15.mp3', '', 1761754199, 1761754199),
(47782, 'Job 29:16', 'Job', 29, 16, 'زۀ د ضرورتمندو د پلار په شان وم، او د مسافرو مرسته به مې کوله.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job29_verse_16.mp3', '', 1761754199, 1761754199),
(47783, 'Job 29:17', 'Job', 29, 17, 'ما د ظالمانو ژامنې ماتې کړې، او د هغوئ نه مې مظلومان خلاص کړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job29_verse_17.mp3', '', 1761754199, 1761754199),
(47784, 'Job 29:18', 'Job', 29, 18, 'زما خيال دا وو چې ډېر عُمر به ژوندے يم او په آرام سره به په کور کښې مړ شم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job29_verse_18.mp3', '', 1761754199, 1761754199),
(47785, 'Job 29:19', 'Job', 29, 19, 'زۀ د داسې ونې په شان وم چې جرړې يې اوبو ته رسېدلې وى او څانګې يې ټوله شپه په پرخه لامدې وى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job29_verse_19.mp3', '', 1761754199, 1761754199),
(47786, 'Job 29:20', 'Job', 29, 20, 'خلقو به هر وخت زما صِفت کولو او زما په مټو به لا هم زور زياتېدو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job29_verse_20.mp3', '', 1761754199, 1761754199),
(47787, 'Job 29:21', 'Job', 29, 21, 'هر چا به زما نصيحت اورېدو، او په خاموشۍ سره به زما د خبرې په انتظار کښې ناست وُو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job29_verse_21.mp3', '', 1761754199, 1761754199),
(47788, 'Job 29:22', 'Job', 29, 22, 'کله چې ما خبرې وکړې نو هغوئ بيا څۀ ونۀ وئيل، او زما خبرې په هغوئ لکه د شاتو لګېدې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job29_verse_22.mp3', '', 1761754199, 1761754199),
(47789, 'Job 29:23', 'Job', 29, 23, 'هغوئ زما د خبرو داسې اِنتظار کولو لکه چې د باران اِنتظار کوى، په هغوئ باندې زما خبرې د سپرلى د باران په شان لګېدې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job29_verse_23.mp3', '', 1761754199, 1761754199),
(47790, 'Job 29:24', 'Job', 29, 24, 'کله چې هغوئ بې‌حوصلې وُو نو ما د هغوئ ډاډګيرنه کوله، او زما په وجه د هغوئ حوصله مضبوطه شوه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job29_verse_24.mp3', '', 1761754199, 1761754199),
(47791, 'Job 29:25', 'Job', 29, 25, 'ما د مشر په شان هغوئ ته وښودل چې څۀ به کوى، زۀ د لښکر د بادشاه په شان د هغوئ سره اوسېدم، او غمژنو له مې تسلى ورکوله.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job29_verse_25.mp3', '', 1761754199, 1761754199),
(47792, 'Psalms 86:1', 'Psalms', 86, 1, 'ای څښتنه سوال مې واوره او قبول یې کړه ځکه چې زه یمه کمزوری حاجتمند یمه زه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms86_verse_1.mp3', '', 1761754199, 1761754199),
(47793, 'Psalms 86:2', 'Psalms', 86, 2, 'له مرګ مې وساته ته ځکه چې یمه وفادار تاته ای زما خدایه، ته مې وژغوره ځکه چې زه ستا خدمتګار یم او په تا باندې باور لرمه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms86_verse_2.mp3', '', 1761754199, 1761754199),
(47794, 'Psalms 86:3', 'Psalms', 86, 3, 'ای څښتنه، په ما رحم وکړه ځکه تاته کړم فریاد ټوله ورځ', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms86_verse_3.mp3', '', 1761754199, 1761754199),
(47795, 'Psalms 86:4', 'Psalms', 86, 4, 'خپل خادم دې کړه خوشحاله ځکه ستا درګاه ته زه دعا کومه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms86_verse_4.mp3', '', 1761754199, 1761754199),
(47796, 'Psalms 86:5', 'Psalms', 86, 5, 'ای څښتنه نېک یې ته بخښونکی یې د هغه چا سره کوې مینه تلپاتې چې کړي سوال درڅخه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms86_verse_5.mp3', '', 1761754199, 1761754199),
(47797, 'Psalms 86:6', 'Psalms', 86, 6, 'ای څښتنه واوره ته دعا زما زما د مرستې زارۍ واوره', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms86_verse_6.mp3', '', 1761754199, 1761754199),
(47798, 'Psalms 86:7', 'Psalms', 86, 7, 'زه فریاد کومه تاته سخته ورځ کې ځکه چې ته مې دعاګانو ته ځواب ورکوې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms86_verse_7.mp3', '', 1761754199, 1761754199),
(47799, 'Psalms 86:8', 'Psalms', 86, 8, 'ای څښتنه بل څوک نشته ستا په مثل معبودانو د دنیا کې تا چې کړي کوم کارونه بل څوک نه یې شي کولای', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms86_verse_8.mp3', '', 1761754199, 1761754199),
(47800, 'Psalms 86:9', 'Psalms', 86, 9, 'چې پیدا کړي دي تا ټول قومونه تاته به راشي او سجده به وکړي او هم به ستا نوم ته جلال ورکړي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms86_verse_9.mp3', '', 1761754199, 1761754199),
(47801, 'Psalms 86:10', 'Psalms', 86, 10, 'دا چې ته لوی او کوې ته عجیبه کارونه نو همدا ته یوازېنی خدای یې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms86_verse_10.mp3', '', 1761754199, 1761754199),
(47802, 'Psalms 86:11', 'Psalms', 86, 11, 'ای څښتنه وښایه ماته دې ته خپله لاره چې زه د ستا رښتینولۍ کې قدم پورته کړمه او داسې زړه راکړه چې وېره وکړمه ستا له نومه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms86_verse_11.mp3', '', 1761754199, 1761754199),
(47803, 'Psalms 86:12', 'Psalms', 86, 12, 'ای څښتنه، ای زما خدایه د زړه له کومي به کړم ستا صفت د تل دپاره به ستا نوم ته زه جلال ورکوم', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms86_verse_12.mp3', '', 1761754199, 1761754199),
(47804, 'Psalms 86:13', 'Psalms', 86, 13, 'ځکه چې ستا مینه ده عظیمه ماته د قبر تل نه دې ژغورلی یم زه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms86_verse_13.mp3', '', 1761754199, 1761754199),
(47805, 'Psalms 86:14', 'Psalms', 86, 14, 'ای خدایه، په ما حمله کوي مغروره خلک یوه ظالمه ډله هڅه کړي چې ومې وژني هماغه ډله ده چې نه لري د ستا پروا', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms86_verse_14.mp3', '', 1761754199, 1761754199),
(47806, 'Psalms 86:15', 'Psalms', 86, 15, 'خو ای څښتنه، ته رحیم او مهربانه خدای یې نه په قهرېږې زر ته ډېره مینه او وفا کوې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms86_verse_15.mp3', '', 1761754199, 1761754199),
(47807, 'Psalms 86:16', 'Psalms', 86, 16, 'ای څښتنه نظر وکړه زما په لوري په ما رحم وکړه خپل ځواک دې راکړه او ما وژغوره داسې خدمت دې زه کومه چې مې مور کړی دی', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms86_verse_16.mp3', '', 1761754199, 1761754199),
(47808, 'Psalms 86:17', 'Psalms', 86, 17, 'راته دې نښه د نېکۍ وښایه ای څښتنه ما سره مرسته وکړه ماته تسلي راکړه وبه شرمیږي دښمنان زما چې وویني دا', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms86_verse_17.mp3', '', 1761754199, 1761754199),
(47809, 'Numbers 2:1', 'Numbers', 2, 1, 'څښتن موسی او هارون ته وویل:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers2_verse_1.mp3', '', 1761754199, 1761754199),
(47810, 'Numbers 2:2', 'Numbers', 2, 2, '«کله چې اسراییلیان خېمې ودروي، هر سړی به د خپلې ډلې د بیرغ او د خپلې طایفې د نښان لاندې خېمې ودروي. کمپ دې د سپېڅلې خېمې په شاوخوا کې جوړ شي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers2_verse_2.mp3', '', 1761754199, 1761754199);